/////////////////////////////////
// cp_atpwalk1, cp_atpwalk0
//   Walk a 1 and a 0 through the non-MODE bits of hgatp and vsatp
/////////////////////////////////



#if (__riscv_xlen == 64 && defined(UDB_SV39X4_TRANSLATION)) || (__riscv_xlen == 32 && defined(UDB_SV32X4_TRANSLATION))
  csrr x6, hgatp
#if __riscv_xlen == 64
  LI(x13, 0x8000000000000000)
  LI(x14, (~SATP64_PPN | ((1 << (UDB_PHYS_ADDR_WIDTH - 12)) - 1)))
#else
  LI(x13, 0x80000000)
  LI(x14, (~SATP32_PPN | ((1 << (UDB_PHYS_ADDR_WIDTH - 12)) - 1)))
#endif
  LI(x8, 0x1)
  or x8, x8, x13
HSm_mcsr_cg_cp_atpwalk1_hgatp_0:
  csrw hgatp, x8
  csrr x9, hgatp
  and x9, x9, x14
  # Check if x9 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x9, HSm_mcsr_cg_cp_atpwalk1_hgatp_0, HSm_mcsr_cg_cp_atpwalk1_hgatp_0_str)
  LI(x8, 0x2)
  or x8, x8, x13
HSm_mcsr_cg_cp_atpwalk1_hgatp_1:
  csrw hgatp, x8
  csrr x9, hgatp
  and x9, x9, x14
  # Check if x9 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x9, HSm_mcsr_cg_cp_atpwalk1_hgatp_1, HSm_mcsr_cg_cp_atpwalk1_hgatp_1_str)
  LI(x8, 0x4)
  or x8, x8, x13
HSm_mcsr_cg_cp_atpwalk1_hgatp_2:
  csrw hgatp, x8
  csrr x9, hgatp
  and x9, x9, x14
  # Check if x9 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x9, HSm_mcsr_cg_cp_atpwalk1_hgatp_2, HSm_mcsr_cg_cp_atpwalk1_hgatp_2_str)
  LI(x8, 0x8)
  or x8, x8, x13
HSm_mcsr_cg_cp_atpwalk1_hgatp_3:
  csrw hgatp, x8
  csrr x9, hgatp
  and x9, x9, x14
  # Check if x9 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x9, HSm_mcsr_cg_cp_atpwalk1_hgatp_3, HSm_mcsr_cg_cp_atpwalk1_hgatp_3_str)
  LI(x8, 0x10)
